.theme-btn{width:27px;height:27px;border-radius:50%;border:1px solid #281408;background:transparent;cursor:pointer;font-size:14px;line-height:1;display:flex;align-items:center;justify-content:center;flex-shrink:0;padding:0;transition:border-color .15s}
