/* ── Language ──────────────────────────────────── */
function applyLang(){
  qa('[data-en]').forEach(function(e){
    var v=L==='th'?(e.getAttribute('data-th')||e.getAttribute('data-en')):e.getAttribute('data-en');
    if(v!=null)e.textContent=v;
  });
  qa('[data-pen]').forEach(function(e){
    var v=L==='th'?(e.getAttribute('data-pth')||e.getAttribute('data-pen')):e.getAttribute('data-pen');
    if(v!=null)e.setAttribute('placeholder',v);
  });
  for(var k in P)fillSel(k+'_sel',P[k]);
  drawTraits();
}
function fillSel(id,arr){
  var s=el(id);if(!s)return;
  var i=Math.max(0,s.selectedIndex);
  s.innerHTML='';
  arr.forEach(function(o){var op=document.createElement('option');op.textContent=L==='th'?o.th:o.en;s.appendChild(op);});
  s.selectedIndex=i;
}
el('lg_en').addEventListener('click',function(){L='en';el('lg_en').classList.add('on');el('lg_th').classList.remove('on');applyLang();});
el('lg_th').addEventListener('click',function(){L='th';el('lg_th').classList.add('on');el('lg_en').classList.remove('on');applyLang();});

/* ── Theme toggle ──────────────────────────────── */
el('btn_theme').addEventListener('click',function(){
  var s=el('app').classList.toggle('theme-s');
  this.textContent=s?'🌑':'🌸';
});

/* ── Panel navigation ──────────────────────────── */
function goPanel(idx){
  if(idx<0||idx>=PANELS.length)return;
  PANELS.forEach(function(id,i){
    qa('[data-panel="'+PANELS[i]+'"]').forEach(function(p){p.classList.toggle('on',i===idx);});
    var tab=document.querySelector('.tab[data-to="'+PANELS[i]+'"]');
    if(tab){tab.classList.toggle('on',i===idx);tab.classList.toggle('been',i<idx);}
  });
  cur=idx;
  el('btn_back').classList.toggle('ghost',idx===0);
  el('btn_next').classList.toggle('ghost',idx===PANELS.length-1);
}
el('btn_next').addEventListener('click',function(){goPanel(cur+1);});
el('btn_back').addEventListener('click',function(){goPanel(cur-1);});
qa('.tab').forEach(function(tab){
  tab.addEventListener('click',function(){
    var idx=PANELS.indexOf(tab.getAttribute('data-to'));
    if(idx>=0)goPanel(idx);
  });
});

/* ── Choice toggles ────────────────────────────── */
qa('.choice').forEach(function(c){
  qa('.choice-b',c).forEach(function(b){
    b.addEventListener('click',function(){
      qa('.choice-b',c).forEach(function(x){x.classList.remove('on');});
      b.classList.add('on');
      var f=c.getAttribute('data-f'),m=b.getAttribute('data-m');
      var sel=el(f+'_sel'),cus=el(f+'_cus');
      if(sel)sel.parentNode.classList.toggle('hidden',m!=='p');
      if(cus)cus.classList.toggle('hidden',m!=='c');
    });
  });
});
function getPC(f){
  var c=document.querySelector('.choice[data-f="'+f+'"]');if(!c)return'';
  var m=c.querySelector('.choice-b.on').getAttribute('data-m');
  if(m==='p'){var s=el(f+'_sel');return s?s.value:'';}
  var cu=el(f+'_cus');return cu?(cu.value||'').trim():'';
}

