/* ── Trait system ──────────────────────────────── */
var traitMode='h';
var SEL={};
function drawTraits(){
  var arr=traitMode==='h'?HT:DT;
  var h='';
  arr.forEach(function(t){
    var nm=L==='th'?t.th:t.name;
    var sk=L==='th'?t.st:t.skill;
    var ds=L==='th'?t.dt:t.desc;
    var num=t.id.replace(/[a-z]/g,'');
    h+='<div class="trait-card'+(SEL[t.id]?' on':'')+'" data-id="'+esc(t.id)+'">'+
      '<div class="t-num">No.'+num+'</div>'+
      '<div class="t-name">'+esc(nm)+'</div>'+
      '<div class="t-skill">'+esc(sk)+'</div>'+
      '<div class="t-desc">'+esc(ds)+'</div>'+
    '</div>';
  });
  el('trait_grid').innerHTML=h;
  qa('.trait-card').forEach(function(card){
    card.addEventListener('click',function(){
      var id=card.getAttribute('data-id');
      if(SEL[id])delete SEL[id];else SEL[id]=true;
      card.classList.toggle('on');
      el('trait_n').textContent=Object.keys(SEL).length;
    });
  });
}
el('tt_human').addEventListener('click',function(){
  traitMode='h';this.classList.add('on');el('tt_demon').classList.remove('on');drawTraits();
});
el('tt_demon').addEventListener('click',function(){
  traitMode='d';this.classList.add('on');el('tt_human').classList.remove('on');drawTraits();
});

/* ── Submit ────────────────────────────────────── */
el('btn_seal').addEventListener('click',function(){
  function v(id){var e=el(id);return e?(e.value||'').trim():'';}
  var abilities=[];
  qa('#ab_list .dyn-item').forEach(function(it){
    var n=(it.querySelector('.ab_n').value||'').trim();
    var h=(it.querySelector('.ab_h').value||'').trim();
    var l=(it.querySelector('.ab_l').value||'').trim();
    if(n||h||l)abilities.push({name:n,how:h,limits:l});
  });
  var weaknesses=[];
  qa('#wk_list .dyn-item').forEach(function(it){
    var t=(it.querySelector('.wk_t').value||'').trim();if(t)weaknesses.push(t);
  });
  var traits=[];
  for(var k in SEL){
    var all=HT.concat(DT);
    for(var i=0;i<all.length;i++){if(all[i].id===k){traits.push({id:k,name:all[i].name,skill:all[i].skill,type:k[0]==='h'?'human':'demon'});break;}}
  }
  var data={
    lang:L,
    name:v('f_name'),age:v('f_age'),gender:v('f_gender'),blood_type:v('f_blood'),
    character_type:getPC('ctype'),era:getPC('era'),rank:getPC('rank'),
    affiliation:getPC('affil'),opening_scene:getPC('scene'),
    prana_style:getPC('breath'),prana_detail:v('f_bdetail'),
    mark_status:segVal('mark_seg'),
    blood_demon_art:v('f_bda'),blood_demon_detail:v('f_bdad'),
    abilities:abilities,traits:traits,
    appearance:v('f_app'),nature:v('f_nat'),history:v('f_hist'),weaknesses:weaknesses
  };
  el('overlay').classList.add('on');
  var payload='<'+'KNY_CONFIRM'+'>\n'+JSON.stringify(data,null,2)+'\n<'+'/KNY_CONFIRM'+'>';
  setTimeout(function(){
    try{
      var w=window.parent||window;
      var ta=w.document.getElementById('send_textarea')||w.document.querySelector('textarea.chat-input,#textareaAutosize,textarea');
      if(ta){
        var d=Object.getOwnPropertyDescriptor(w.HTMLTextAreaElement.prototype,'value');
        if(d&&d.set)d.set.call(ta,payload);else ta.value=payload;
        ta.dispatchEvent(new Event('input',{bubbles:true}));
        setTimeout(function(){try{var sb=w.document.getElementById('send_but');if(sb)sb.click();else ta.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));}catch(e){}},150);
        return;
      }
    }catch(e){}
    try{navigator.clipboard.writeText(payload);}catch(e){}
  },450);
});

/* ── Init ──────────────────────────────────────── */
goPanel(0);applyLang();drawTraits();
})();
